mapper.select:
SELECT t1.id, t1.name, t1.type, t1.balance, t1.is_include_total_assets, t1.remark, t1.create_time FROM jz_accounts t1 WHERE t1.is_deleted = 0
AND t1.user_id = #{queryParams.userId}
AND t1.name LIKE CONCAT('%', #{queryParams.name}, '%')
AND t1.type = #{queryParams.type}
ORDER BY t1.create_time DESC
